'use strict';
const $=s=>document.querySelector(s),money=(n,d=0)=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',minimumFractionDigits:d,maximumFractionDigits:d}).format(n),num=(n,d=0)=>new Intl.NumberFormat('en-GB',{maximumFractionDigits:d}).format(n),date=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}),stamp=d=>new Date(d).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let filters={search:'',category:'all',supplier:'all',risk:'all',sort:'risk',direction:1},catalogueCategory='all',catalogueSearch='',scenario={demand:0,promo:0,selected:[6],delay:0,supplierId:'all',budget:state.settings.budget,days:30},timer;
const ICONS={Overview:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',Inventory:'M3 7l9-4 9 4v11l-9 4-9-4zM3 7l9 4 9-4M12 11v11',Recommendations:'M9 18h6M10 21h4M8 14a6 6 0 1 1 8 0l-1 2H9z','Purchase orders':'M6 3h12v18H6zM9 7h6M9 11h6M9 15h4',Suppliers:'M3 15V6h12v9zM15 9h4l3 4v2h-7M5 18a2 2 0 1 0 0-.1M18 18a2 2 0 1 0 0-.1','Scenario planner':'M5 3v18M12 3v18M19 3v18M3 7h4M10 15h4M17 10h4',Performance:'M3 21h18M6 17V9M12 17V3M18 17v-6','Help and guidance':'M9 8a3 3 0 1 1 5 2l-2 2v2M12 17h.01M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20',Settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2'};
const NAV=[['Overview','overview'],['Inventory','inventory'],['Recommendations','recommendations'],['Purchase orders','orders'],['Suppliers','suppliers'],['Scenario planner','scenario'],['Performance','performance'],['Help and guidance','help'],['Settings','settings']];
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICONS[n]}"/></svg>`;
const logo=()=>`<a class="logo" href="#overview"><img src="favicon.svg" alt="NovaGoods brand mark">novagoods<span style="color:#68baa3">.</span></a>`;
function photo(p,cls=''){return `<img class="${cls}" src="${esc(PHOTO_URLS[p.type]||'')}" alt="Illustrative ${esc(p.type.replaceAll('_',' '))} photograph" loading="lazy" referrerpolicy="no-referrer">`}
function badge(r){return `<span class="tag ${r==='Stockout risk'||r==='Out of stock'?'red':r==='Overstock'||r==='No demand'?'amber':'teal'}">${r}</span>`}
function stat(label,value,hint,route='',tone=''){return `<${route?'a':'div'} ${route?`href="#${route}"`:''} class="stat"><div class="label">${label}</div><div class="value ${tone}">${value}</div><div class="hint">${hint}</div></${route?'a':'div'}>`}
function heading(title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">Merchandising workspace</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',5000)}
function openModal(html){const m=$('#modal');m.innerHTML=`<button class="close" aria-label="Close dialog" onclick="closeModal()">×</button>${html}`;m.showModal()}
function closeModal(){$('#modal').close()}
function navigate(route){location.hash=route}
function chart(series,labels,options={}){const w=720,h=235,left=45,top=20,bottom=35;let max=Math.max(1,...series.flatMap(s=>s.values.filter(v=>v!==null)));if(options.max)max=options.max;const n=labels.length;const x=i=>left+i*(w-left-15)/(Math.max(1,n-1)),y=v=>h-bottom-(v/max)*(h-bottom-top);let svg=`<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(options.title||'Sales and forecast chart')}">`;for(let i=0;i<=4;i++){let v=max*i/4;svg+=`<line class="gridline" x1="${left}" y1="${y(v)}" x2="${w-10}" y2="${y(v)}"/><text x="${left-9}" y="${y(v)+4}" text-anchor="end">${num(v)}</text>`}if(options.band){const b=options.band;svg+=`<polygon points="${b.high.map((v,i)=>`${x(i)},${y(v)}`).join(' ')} ${b.low.map((v,i)=>`${x(n-1-i)},${y(b.low[n-1-i])}`).join(' ')}" fill="#dceee8" opacity=".7"/>`;}series.forEach(s=>{let points=[];s.values.forEach((v,i)=>{if(v!==null)points.push(`${x(i)},${y(v)}`)});svg+=`<polyline fill="none" stroke="${s.color}" stroke-width="2.5" ${s.dash?'stroke-dasharray="6 5"':''} points="${points.join(' ')}"/>`;});labels.forEach((l,i)=>{if(i===0||i===n-1||i%Math.max(1,Math.floor(n/5))===0)svg+=`<text x="${x(i)}" y="${h-8}" text-anchor="middle">${esc(l)}</text>`});return svg+'</svg>'}
function route(){return (location.hash.slice(1)||'overview').split('?')[0]}
function render(){const path=route();if(path.startsWith('public'))return renderPublic(path);const key=path.split('/')[0],title=NAV.find(n=>n[1]===key)?.[0]||(key==='product'?'Inventory':'Help and guidance');$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${logo()}<div class="brand-caption">Stock Planner</div><nav aria-label="Workspace">${NAV.map(([name,r])=>`<a href="#${r}" class="${key===r||key==='product'&&r==='inventory'?'active':''}" ${key===r?'aria-current="page"':''}>${icon(name)}${name}${r==='recommendations'&&totals().pending?`<span class="tag" style="margin-left:auto;background:#365a59;color:white">${totals().pending}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><a href="#public/home" style="color:#c6ded8;font-size:14px">Visit NovaGoods website</a><div class="demo">Fictional company · Interactive demo</div><div class="profile"><div class="avatar">SG</div><div><strong>Sofia Greco</strong><small>Senior Merchandiser</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="mobile-brand">${logo()}</div><div class="crumb">Workspace <strong>/ ${title}</strong></div><div class="top-actions"><span class="subtle">Planning snapshot · 9 Oct 2026</span><a href="#help" aria-label="Help and guidance">Help</a><div class="avatar" title="Sofia Greco">SG</div></div></header><main id="main" class="main">${view(path)}<footer class="app-footer"><span>40 demonstration products · GBP · Warehouse: Manchester</span><span>Fictional company · Interactive demo</span></footer></main></div></div>`;if(key==='scenario')bindScenario();}
function view(path){let [key,id]=path.split('/');switch(key){case'overview':return overview();case'inventory':return inventory();case'product':return product(Number(id));case'recommendations':return recommendations();case'orders':return id?orderDetail(id):orders();case'suppliers':return id?supplierDetail(id):suppliers();case'scenario':return scenarioView();case'performance':return performance();case'help':return id?helpArticle(id):help();case'settings':return settings();default:return helpArticle('review')}}
function overview(){const t=totals(),risk=t.rows.filter(x=>x.m.out!==null).sort((a,b)=>b.m.revenue-a.m.revenue),daily=PRODUCTS.reduce((a,p)=>a+forecast(p),0),hist=Array.from({length:12},(_,i)=>PRODUCTS.reduce((a,p)=>a+(p.history[i]||0),0));const labels=['20 Jul','27 Jul','3 Aug','10 Aug','17 Aug','24 Aug','31 Aug','7 Sep','14 Sep','21 Sep','28 Sep','5 Oct','12 Oct','19 Oct','26 Oct','2 Nov'];let forecastLine=Array(11).fill(null).concat([hist[11],...Array(4).fill(Math.round(daily*7))]);return `${heading('A clearer view of what comes next.','Good morning, Sofia. Here are the stock decisions that need your attention.',`<a class="button" href="#scenario">Explore scenarios</a>`)}${state.applied?'<div class="warning">An explicitly applied scenario is being used for planning. Warehouse stock is unchanged. <button class="link-button" onclick="clearApplied()">Return to baseline</button></div>':''}<div class="cards">${stat('Products at risk of stockout',t.risk,'Next 30 days · includes depleted stock','inventory?risk=Stockout risk','red')}${stat('Estimated revenue at risk',money(t.revenue),'30-day unmet units × retail price','inventory?risk=Stockout risk','red')}${stat('Cash tied up in overstock',money(t.over),'Units above 12 weeks × unit cost','inventory?risk=Overstock','amber')}${stat('Recommendations to review',t.pending,'Buyer decisions required','recommendations')}${stat('Draft purchase order value',money(t.draft),'Committed only after approval','orders')}</div><div class="grid-two"><section class="panel"><div class="panel-head"><h2>Demand, with a view ahead</h2><span class="tag">All 40 products</span></div><div class="legend"><span class="grey">Historical sales</span><span>Baseline forecast</span><span class="light">Simulated ±25% range</span></div>${chart([{values:hist.concat(Array(4).fill(null)),color:'#8dabb6'},{values:forecastLine,color:'#147565',dash:true}],labels,{title:'Weekly historical sales and baseline forecast in units',band:{high:Array(12).fill(0).concat(Array(4).fill(daily*7*1.25)),low:Array(12).fill(0).concat(Array(4).fill(daily*7*.75))}})}<div class="note">Weekly units sold. Missing sales are omitted; promotional and seasonal adjustments are included in the forward estimate. <a href="#help/forecast">How forecasting works</a></div></section><section class="panel"><div class="panel-head"><h2>Warehouse at a glance</h2><a href="#inventory">View inventory</a></div><div class="availability"><div class="ring" style="--pct:${PRODUCTS.filter(p=>p.stock-p.reserved>0).length/40*100}%"><strong>${num(PRODUCTS.filter(p=>p.stock-p.reserved>0).length/40*100,1)}%</strong></div><div><strong>Products available now</strong><div class="subtle">${PRODUCTS.filter(p=>p.stock-p.reserved>0).length} of 40 lines have available units</div></div></div><dl class="key-values"><dt>Available units</dt><dd>${num(t.units)}</dd><dt>Available stock at cost</dt><dd>${money(t.stockCash)}</dd><dt>Incoming deliveries</dt><dd>${PRODUCTS.reduce((a,p)=>a+deliveries(p).length,0)}</dd><dt>Gross profit at risk, 30 days</dt><dd>${money(t.gross)}</dd></dl><div class="note">Stock value is a cash measure. Revenue and gross profit are separate estimates; they are not savings.</div></section></div><div class="grid-two"><section class="panel"><div class="panel-head"><h2>Decisions needed today</h2><a href="#recommendations">Review all</a></div>${risk.slice(0,4).map(({p,m})=>`<div class="decision">${photo(p)}<div class="decision-info"><strong><a href="#product/${p.id}">${p.name}</a></strong><div class="subtle">${p.sku} · ${m.out===0||m.out===1?'Already depleted or less than one day':num(m.cover,1)+' days cover'} · ${money(m.revenue)} estimated revenue at risk</div></div>${badge(m.risk)}<button onclick="review(${p.id})">Review</button></div>`).join('')}${!risk.length?'<p class="subtle">No stockouts projected over the next 30 days.</p>':''}</section><section class="panel"><div class="panel-head"><h2>Beyond the spreadsheet</h2></div><div class="accent-line"></div><h3>What if Black Friday arrives early?</h3><p class="subtle">Compare a demand surge, late deliveries or a tighter budget before committing to a purchase.</p><a class="button primary" href="#scenario">Open scenario planner</a><div class="note" style="margin-top:20px">Company-wide context: 1,250 active lines, roughly £38m annual turnover. This workspace uses a separate 40-product sample.</div></section></div><div class="intro-banner"><span><strong>Buyers stay in control.</strong> Recommendations become draft orders only after your review.</span><a href="#help/oversight">Human oversight policy</a></div>`}
function readQuery(){let q=new URLSearchParams(location.hash.split('?')[1]||'');if(q.has('risk'))filters.risk=q.get('risk')}
function inventory(){readQuery();return `${heading('Inventory','One warehouse. Every product, incoming delivery and stock risk in view.')}<div class="filters"><input aria-label="Search inventory" placeholder="Search products or SKU…" value="${esc(filters.search)}" oninput="setFilter('search',this.value)"><select aria-label="Category" onchange="setFilter('category',this.value)">${options(['all',...new Set(PRODUCTS.map(p=>p.category))],filters.category,'All categories')}</select><select aria-label="Supplier" onchange="setFilter('supplier',this.value)"><option value="all">All suppliers</option>${SUPPLIERS.map(s=>`<option value="${s.id}" ${filters.supplier===s.id?'selected':''}>${s.name}</option>`).join('')}</select><select aria-label="Risk" onchange="setFilter('risk',this.value)">${options(['all','Stockout risk','Out of stock','Overstock','No demand','Healthy'],filters.risk,'All risks')}</select><button onclick="resetFilters()">Clear</button></div><div id="inventory-table">${inventoryTable()}</div><p class="subtle">Stock cover = available units ÷ average daily forecast. Incoming deliveries are shown separately and included in the stock projection.</p>`}
function options(values,current,all='All'){return values.map(v=>`<option value="${v}" ${v===current?'selected':''}>${v==='all'?all:v}</option>`).join('')}
function setFilter(k,v){filters[k]=v;$('#inventory-table').innerHTML=inventoryTable()}
function resetFilters(){filters={search:'',category:'all',supplier:'all',risk:'all',sort:'risk',direction:1};location.hash='inventory';render()}
function sortBy(k){filters.direction=filters.sort===k?-filters.direction:1;filters.sort=k;$('#inventory-table').innerHTML=inventoryTable()}
function inventoryRows(){return PRODUCTS.filter(p=>{let m=plan(p);return (!filters.search||`${p.name} ${p.sku}`.toLowerCase().includes(filters.search.toLowerCase()))&&(filters.category==='all'||p.category===filters.category)&&(filters.supplier==='all'||p.supplierId===filters.supplier)&&(filters.risk==='all'||(filters.risk==='Stockout risk'?m.out!==null:filters.risk==='Overstock'?m.over>0:m.risk===filters.risk))}).sort((a,b)=>{let ma=plan(a),mb=plan(b),v=filters.sort==='name'?a.name.localeCompare(b.name):filters.sort==='stock'?(a.stock-a.reserved)-(b.stock-b.reserved):filters.sort==='cover'?(ma.cover??9999)-(mb.cover??9999):mb.revenue-ma.revenue;return v*filters.direction})}
function productCell(p){return `<div class="product-cell">${photo(p)}<div><a href="#product/${p.id}">${p.name}</a><small>${p.sku} · ${p.category}</small></div></div>`}
function inventoryTable(){const rows=inventoryRows();return `<div class="table-wrap"><table><thead><tr><th><button onclick="sortBy('name')">Product ↕</button></th><th><button onclick="sortBy('stock')">Available ↕</button></th><th>Incoming</th><th>Forecast / week</th><th><button onclick="sortBy('cover')">Cover ↕</button></th><th><button onclick="sortBy('risk')">Stock status ↕</button></th><th>Supplier</th><th>Reorder</th></tr></thead><tbody>${rows.map(p=>{const m=plan(p),inc=deliveries(p);return `<tr><td>${productCell(p)}</td><td class="number"><strong>${num(p.stock-p.reserved)}</strong><small class="block subtle">${p.reserved} reserved</small></td><td>${num(inc.reduce((a,x)=>a+x.qty,0))}<small class="block subtle">${inc.length?date(inc[0].date):'No delivery scheduled'}</small></td><td>${num(m.daily*7,1)} units</td><td>${m.cover===null?'No demand':num(m.cover,1)+' days'}<div class="cover-bar"><i class="${m.out!==null?'red':m.over?'amber':''}" style="width:${Math.min(100,(m.cover??100)/60*100)}%"></i></div></td><td>${badge(m.risk)}${WARNINGS[p.flag]?'<small class="block subtle">Extra review required</small>':''}</td><td><a href="#suppliers/${p.supplierId}">${supplier(p).name}</a></td><td>${m.qty?`<button onclick="review(${p.id})">${num(m.qty)} units</button>`:'—'}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">No products match these filters. Try clearing them.</td></tr>'}</tbody></table><div class="table-footer"><span>${rows.length} of 40 products</span><span>Current stock is never increased by accepting an order</span></div></div>`}
function product(id){const p=PRODUCTS.find(p=>p.id===id);if(!p)return '<h1>Product not found</h1><a href="#inventory">Back to inventory</a>';const m=plan(p),ins=deliveries(p),d=state.decisions.filter(d=>d.productId===id);let h=p.history.concat(Array(6).fill(null)),f=Array(11).fill(null).concat([p.history[11],...Array(6).fill(m.daily*7)]),labels=Array.from({length:18},(_,i)=>i<12?'W'+(i+1):'F'+(i-11));return `<p><a href="#inventory">Back to inventory</a></p><div class="details-top">${photo(p)}<div><div class="eyebrow">${p.category} · ${p.sku}</div><h1>${p.name}</h1>${badge(m.risk)}<span class="subtle">${money(p.price,2)} retail · ${money(p.cost,2)} unit cost</span></div></div><div class="metric-grid" style="margin-bottom:24px"><div class="metric"><small>Warehouse stock</small><strong>${p.stock}</strong></div><div class="metric"><small>Reserved / available</small><strong>${p.reserved} / ${p.stock-p.reserved}</strong></div><div class="metric"><small>Stock cover</small><strong>${m.cover===null?'No demand':num(m.cover,1)+' days'}</strong></div><div class="metric"><small>First estimated stockout</small><strong style="font-size:19px">${m.out===0?'Already out of stock':m.out!==null?date(dateAt(m.out)):'None in 30 days'}</strong></div></div>${WARNINGS[p.flag]?`<div class="warning"><strong>Extra review required</strong><p>${WARNINGS[p.flag]}</p></div>`:''}<div class="grid-two"><section class="panel"><div class="panel-head"><h2>Sales history & demand forecast</h2><span class="tag">Units / week</span></div><div class="legend"><span class="grey">Actual sales</span><span>Simulated forecast</span></div>${chart([{values:h,color:'#97aeb8'},{values:f,color:'#147565',dash:true}],labels,{title:p.name+' historical weekly sales and simulated forecast'})}<p class="note">12 weeks ending 4 Oct 2026. ${p.flag==='new'?'No sales history before week 10; gaps are not zero sales.':''}Daily estimate: ${num(m.daily,1)} units; indicative range ${num(m.low,1)}–${num(m.high,1)}. The ±25% range is an assumption, not a statistical confidence interval.</p></section><section class="panel"><h2>Buyer recommendation</h2><div style="font:800 36px Manrope">${m.qty?num(m.qty)+' units':'Hold stock'}</div><p class="explain">${explanation(p,m)}</p><dl class="key-values"><dt>Purchase cost</dt><dd>${money(m.spend,2)}</dd><dt>Order by</dt><dd>${m.qty?(m.orderDay<0?'Now · overdue '+Math.abs(m.orderDay)+' days':date(dateAt(m.orderDay))):'No order needed'}</dd><dt>Stock at arrival, before new order</dt><dd>${num(simulate(p,{...operationalOpts(),days:p.lead}).end,1)} units</dd><dt>Stock after arrival, if approved</dt><dd>${num(simulate(p,{...operationalOpts(),days:p.lead}).end+m.qty,1)} units</dd></dl><div class="actions">${m.qty?`<button class="primary" onclick="review(${p.id})">Review recommendation</button>`:''}<button onclick="addNote(${p.id})">Add note</button></div></section></div><div class="grid-two"><section class="panel"><h2>Projected available stock</h2>${chart([{values:m.trace.map(x=>x.stock),color:'#147565'}],m.trace.map(x=>'Day '+x.day),{title:'Projected available stock for 30 days including incoming deliveries'})}<div class="note">Uses daily demand and confirmed incoming dates. Unmet demand is lost, rather than carried forward. Draft orders are excluded.</div><h3 style="margin-top:22px">Incoming deliveries</h3>${ins.map(x=>`<div class="history"><strong>${num(x.qty)} units</strong> · ${date(x.date)}<small>${x.source}</small></div>`).join('')||'<p class="subtle">No incoming deliveries.</p>'}</section><section class="panel"><h2>Supplier constraints</h2><dl class="key-values"><dt>Supplier</dt><dd><a href="#suppliers/${p.supplierId}">${supplier(p).name}</a></dd><dt>Lead time</dt><dd>${p.lead} days</dd><dt>Minimum order</dt><dd>${p.moq} units</dd><dt>Pack size</dt><dd>${p.pack} units</dd><dt>On-time delivery</dt><dd>${supplier(p).reliability}% · 50 sample orders</dd><dt>Specifications</dt><dd style="max-width:230px">${esc(p.specs)}</dd></dl><h3 style="margin-top:25px">Decision history</h3>${d.map(x=>`<div class="history"><strong>${x.kind}${x.qty?' · '+x.qty+' units':''}</strong><p>${esc(x.reason)}</p><small>${x.user} · ${stamp(x.time)}${x.original!==undefined?' · original '+x.original+' units':''}</small></div>`).join('')||'<p class="subtle">No decisions recorded in this demo session.</p>'}</section></div>`}
function explanation(p,m){if(!m.daily)return 'No demand in the last 12 weeks. No replenishment is suggested. Review clearance options and the source data.';if(!m.qty)return m.over?'Available stock exceeds 12 weeks of baseline demand. Pause replenishment and review a controlled markdown or range reduction.':'Available and timely incoming stock cover the lead time plus the planning buffer. No new order is needed.';return `Forecast demand is ${num(m.daily*7,1)} units per week. Target stock covers ${p.lead} days of lead time plus ${state.settings.safety} safety days. After subtracting available units and incoming stock due within that window, order ${num(m.qty)} units, rounded to packs of ${p.pack} and the ${p.moq}-unit minimum. ${m.out!==null?'An order may arrive after the first stockout; consider an expedited delivery.':''}`}
function recommendations(){const rows=PRODUCTS.filter(p=>plan(p).qty>0).sort((a,b)=>plan(b).revenue-plan(a).revenue);return `${heading('Recommendations','Review the assumptions. Make the decision. Keep the audit trail.')}<div class="intro-banner"><span>Accepting a recommendation adds a draft line. A separate purchase order approval is required.</span><a href="#help/review">Review guidance</a></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Recommendation</th><th>Purchase cost</th><th>Order by</th><th>Review status</th><th>Decision</th></tr></thead><tbody>${rows.map(p=>{let m=plan(p),d=latestDecision(p);return `<tr><td>${productCell(p)}${WARNINGS[p.flag]?`<small class="block" style="color:var(--amber)">Extra review: ${p.flag}</small>`:''}</td><td><strong>${num(m.qty)} units</strong><small class="block subtle">MOQ ${p.moq} · pack ${p.pack}</small></td><td>${money(m.spend,2)}</td><td>${m.orderDay<0?'<span class="tag red">Due now</span>':date(dateAt(m.orderDay))}</td><td>${d?`<span class="tag ${d.kind==='Accepted'?'teal':'amber'}">${d.kind}</span><small class="block subtle">${stamp(d.time)}</small>`:'Awaiting review'}</td><td>${d?.kind==='Accepted'?`<a href="#orders/${d.orderId}">View order</a>`:`<button class="primary" onclick="review(${p.id})">Review</button>`}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No replenishment recommendations at this time.</td></tr>'}</tbody></table></div><section class="panel" style="margin-top:24px"><h2>Recent buyer decisions</h2>${state.decisions.slice().reverse().slice(0,8).map(d=>`<div class="history"><a href="#product/${d.productId}">${PRODUCTS.find(p=>p.id===d.productId).name}</a> · <strong>${d.kind}</strong>${d.qty?' · '+d.qty+' units':''}<p>${esc(d.reason)||'Quantity accepted as suggested.'}</p><small>${d.user} · ${stamp(d.time)} · original recommendation ${d.original??'—'} units</small></div>`).join('')||'<p class="subtle">Your decisions will appear here. Historical sample decisions are shown separately in Performance.</p>'}</section>`}
function review(id){const p=PRODUCTS.find(p=>p.id===id),m=plan(p),existing=state.orders.find(o=>o.lines.some(l=>l.productId===id));if(existing){navigate('orders/'+existing.id);toast('This product already has a purchase order line. Review the order to avoid a duplicate.');return}openModal(`<div class="eyebrow">Buyer decision · ${p.sku}</div><h2>${p.name}</h2><p class="subtle">${explanation(p,m)}</p><form id="decision-form" onsubmit="submitDecision(event,${id})"><label for="decision-kind">Decision</label><select id="decision-kind" onchange="updateReview(${id})"><option value="Accepted">Accept / revise quantity</option><option value="Rejected">Reject recommendation</option><option value="Deferred">Defer for review</option></select><div id="quantity-area"><label for="decision-qty">Order quantity · minimum ${p.moq}, packs of ${p.pack}</label><input id="decision-qty" type="number" min="${p.moq}" step="${p.pack}" value="${m.qty||p.moq}" oninput="updateReview(${id})"><div id="decision-impact" class="summary"></div></div><label for="decision-reason">Reason or note <span class="subtle">(required for revisions, rejection or deferral)</span></label><textarea id="decision-reason" placeholder="Record the reasoning for the buying team…"></textarea>${WARNINGS[p.flag]?`<div class="warning">${WARNINGS[p.flag]}</div><label class="check"><input type="checkbox" id="decision-ack">I have reviewed this warning and the source assumptions. I accept responsibility for this demo buying decision.</label>`:''}<div id="decision-error" class="error" role="alert"></div><div class="actions"><button class="primary" type="submit">Save buyer decision</button><button type="button" onclick="closeModal()">Cancel</button></div><p class="note">No real supplier is contacted. Current warehouse stock remains unchanged.</p></form>`);updateReview(id)}
function updateReview(id){const p=PRODUCTS.find(p=>p.id===id),qty=Number($('#decision-qty').value),kind=$('#decision-kind').value;$('#quantity-area').style.display=kind==='Accepted'?'block':'none';$('#decision-qty').required=kind==='Accepted';$('#decision-qty').disabled=kind!=='Accepted';$('#decision-impact').innerHTML=`<strong>${money(Math.max(0,qty)*p.cost,2)} purchase cost</strong><br><span class="subtle">Expected delivery ${date(dateAt(p.lead))}. Projected stock immediately after arrival: ${num(simulate(p,{days:p.lead}).end+Math.max(0,qty),1)} units. ${num(qty/(forecast(p)||1),1)} days of added cover.</span>`}
function submitDecision(e,id){e.preventDefault();const p=PRODUCTS.find(p=>p.id===id),kind=$('#decision-kind').value,qty=Number($('#decision-qty').value),reason=$('#decision-reason').value.trim(),original=plan(p).qty;try{if((kind!=='Accepted'||qty!==original)&&!reason)throw Error('Please give a reason for this decision.');if(kind==='Accepted'){let o=acceptProduct(id,qty,reason,$('#decision-ack')?.checked);toast(`Added ${qty} units to draft ${o.id}.`)}else{state.decisions.push({productId:id,kind,original,qty:null,reason,user:'Sofia Greco',time:new Date().toISOString()});saveState();toast(kind==='Deferred'?'Deferred for buyer review.':'Recommendation rejected with your reason.')}closeModal();render()}catch(err){$('#decision-error').textContent=err.message}}
function addNote(id){openModal(`<h2>Add a buyer note</h2><form onsubmit="saveNote(event,${id})"><label for="buyer-note">Note for ${PRODUCTS.find(p=>p.id===id).name}</label><textarea id="buyer-note" required></textarea><div class="actions"><button class="primary">Save note</button><button type="button" onclick="closeModal()">Cancel</button></div></form>`)}
function saveNote(e,id){e.preventDefault();state.decisions.push({productId:id,kind:'Note',reason:$('#buyer-note').value.trim(),user:'Sofia Greco',time:new Date().toISOString()});saveState();closeModal();render();toast('Buyer note saved.')}
function orders(){return `${heading('Purchase orders','Grouped by supplier. Draft, review, then approve a simulated purchase.')}<div class="cards" style="grid-template-columns:repeat(3,1fr)">${stat('Draft orders',state.orders.filter(o=>o.status==='Draft').length,'Awaiting approval')}${stat('Draft purchase value',money(totals().draft),'Unit purchase costs, excluding freight')}${stat('Approved orders',state.orders.filter(o=>o.status==='Approved').length,'Included in incoming stock')}</div>${state.orders.length?`<div class="table-wrap"><table><thead><tr><th>Order</th><th>Supplier</th><th>Lines</th><th>Total at cost</th><th>Estimated arrival</th><th>Status</th><th></th></tr></thead><tbody>${state.orders.map(o=>`<tr><td><a href="#orders/${o.id}">${o.id}</a><small class="block subtle">Created ${stamp(o.created)}</small></td><td>${SUPPLIERS.find(s=>s.id===o.supplierId).name}</td><td>${o.lines.length}</td><td>${money(orderTotal(o),2)}</td><td>${date(o.arrival)}</td><td><span class="tag ${o.status==='Approved'?'teal':'amber'}">${o.status}</span></td><td><a href="#orders/${o.id}">Review order</a></td></tr>`).join('')}</tbody></table></div>`:`<section class="panel empty"><h2>No purchase orders yet</h2><p>Accept a recommendation to create your first supplier draft.</p><a href="#recommendations" class="button primary">Review recommendations</a></section>`}<p class="subtle">All orders are simulated. Approval creates incoming deliveries and never changes current warehouse stock.</p>`}
function orderDetail(id){const o=state.orders.find(o=>o.id===id);if(!o)return '<h1>Order not found</h1><a href="#orders">Back to orders</a>';const s=SUPPLIERS.find(s=>s.id===o.supplierId);return `<p><a href="#orders">Back to purchase orders</a></p>${heading(o.id,s.name+' · '+s.location,`<span class="tag ${o.status==='Approved'?'teal':'amber'}">${o.status}</span>`)}<div class="intro-banner"><span>Estimated arrival ${date(o.arrival)} · ${s.lead}-day lead time · ${s.terms} terms</span><a href="#suppliers/${s.id}">Supplier details</a></div><div class="table-wrap"><table><thead><tr><th>Product</th><th>Unit cost</th><th>Quantity</th><th>Line total</th><th>Constraints</th><th></th></tr></thead><tbody>${o.lines.map(l=>{let p=PRODUCTS.find(p=>p.id===l.productId);return `<tr><td>${productCell(p)}</td><td>${money(p.cost,2)}</td><td>${o.status==='Draft'?`<input style="width:95px" aria-label="Quantity for ${esc(p.name)}" type="number" min="${p.moq}" step="${p.pack}" value="${l.qty}" onchange="editLine('${o.id}',${p.id},this.value)">`:num(l.qty)}</td><td>${money(p.cost*l.qty,2)}</td><td>MOQ ${p.moq} · pack ${p.pack}</td><td>${o.status==='Draft'?`<button class="danger" onclick="removeLine('${o.id}',${p.id})">Remove</button>`:''}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">This draft is empty. Accept recommendations from this supplier to add lines.</td></tr>'}</tbody></table></div><section class="panel" style="margin-top:24px"><div class="panel-head"><h2>Total purchase cost</h2><strong style="font-size:27px">${money(orderTotal(o),2)}</strong></div><p class="subtle">Demo unit costs exclude VAT and freight. The budget is a purchasing guideline; approval does not spend real money.</p>${orderTotal(o)>state.settings.budget?'<div class="warning">This order exceeds the demo purchasing budget. Review before approval.</div>':''}${o.status==='Draft'?`<button class="primary" ${!o.lines.length?'disabled':''} onclick="confirmApprove('${o.id}')">Approve purchase order</button>`:`<p><strong>Approved by Sofia Greco · ${stamp(o.approved)}</strong></p><p>This order is now included in incoming deliveries. No real supplier was contacted.</p>`}</section>`}
function editLine(id,pid,value){let o=state.orders.find(o=>o.id===id),p=PRODUCTS.find(p=>p.id===pid),qty=Number(value);if(o.status!=='Draft')return;if(!validQty(p,qty)){toast(`Enter at least ${p.moq} units in packs of ${p.pack}.`);render();return}let l=o.lines.find(l=>l.productId===pid);state.decisions.push({productId:pid,kind:'Order quantity revised',original:l.original,qty,reason:`Draft ${id}: ${l.qty} → ${qty} units`,orderId:id,user:'Sofia Greco',time:new Date().toISOString()});l.qty=qty;saveState();render();toast('Draft quantity updated.')}
function removeLine(id,pid){openModal(`<h2>Remove this order line?</h2><p>${PRODUCTS.find(p=>p.id===pid).name} will be removed from draft ${id}. Its recommendation will be available to review again.</p><div class="actions"><button class="danger" onclick="doRemoveLine('${id}',${pid})">Remove line</button><button onclick="closeModal()">Keep line</button></div>`)}
function doRemoveLine(id,pid){let o=state.orders.find(o=>o.id===id);if(o.status!=='Draft')return;let l=o.lines.find(l=>l.productId===pid);o.lines=o.lines.filter(l=>l.productId!==pid);state.decisions.push({productId:pid,kind:'Line removed',qty:null,original:l.original,reason:'Removed from draft '+id,user:'Sofia Greco',time:new Date().toISOString()});saveState();closeModal();render();toast('Line removed from draft.')}
function confirmApprove(id){const o=state.orders.find(o=>o.id===id);openModal(`<h2>Approve simulated purchase?</h2><p>Approve ${o.id} for <strong>${money(orderTotal(o),2)}</strong>, containing ${o.lines.length} product lines.</p><p>Incoming stock will be scheduled for ${date(o.arrival)}. Current warehouse quantities will stay as they are.</p><div class="warning">This is a demo approval. No real supplier is contacted and no payment is made.</div><div class="actions"><button class="primary" onclick="doApprove('${id}')">Confirm demo approval</button><button onclick="closeModal()">Return to draft</button></div>`)}
function doApprove(id){try{approveOrder(id);closeModal();render();toast('Order approved. Its units now appear as incoming stock.')}catch(e){toast(e.message)}}
function suppliers(){return `${heading('Suppliers','Six fictional trading partners, with delivery records and practical buying constraints.')}<div class="supplier-grid">${SUPPLIERS.map(s=>`<a href="#suppliers/${s.id}" class="supplier-card" style="color:inherit;text-decoration:none"><span class="tag ${s.reliability<85?'amber':'teal'}">${s.location}</span><h3>${s.name}</h3><p class="subtle">${s.story}</p><div class="progress"><i style="width:${s.reliability}%"></i></div><div class="panel-head" style="font-size:14px"><strong>${s.reliability}% on-time</strong><span>${s.lead} days lead</span></div><dl class="key-values"><dt>Linked products</dt><dd>${PRODUCTS.filter(p=>p.supplierId===s.id).length}</dd><dt>Open orders</dt><dd>${state.orders.filter(o=>o.supplierId===s.id).length}</dd><dt>Minimum / pack</dt><dd>${s.moq} / ${s.pack} units</dd></dl></a>`).join('')}</div><p class="subtle">Reliability is the proportion of 50 historical sample orders delivered by their agreed date. Supplier identities and contacts are fictional.</p>`}
function supplierDetail(id){const s=SUPPLIERS.find(s=>s.id===id);if(!s)return '<h1>Supplier not found</h1>';return `<p><a href="#suppliers">Back to suppliers</a></p>${heading(s.name,s.location+' · Fictional supplier')}<div class="grid-two"><section class="panel"><h2>Trading profile</h2><p>${s.story}</p><dl class="key-values"><dt>Lead time</dt><dd>${s.lead} days</dd><dt>Minimum per product</dt><dd>${s.moq} units</dd><dt>Reorder pack</dt><dd>${s.pack} units</dd><dt>Terms</dt><dd>${s.terms}</dd><dt>On-time reliability</dt><dd>${s.reliability}% of 50 sample orders</dd><dt>Demo contact</dt><dd>${s.contact}</dd></dl>${s.reliability<85?'<div class="warning">Variable arrival dates. Confirm shipping schedules and consider a contingency before approving a purchase.</div>':''}</section><section class="panel"><h2>Open orders</h2>${state.orders.filter(o=>o.supplierId===id).map(o=>`<div class="history"><a href="#orders/${o.id}">${o.id}</a> · ${o.status}<p>${money(orderTotal(o),2)} · Arrival ${date(o.arrival)}</p></div>`).join('')||'<p class="subtle">No open orders for this supplier.</p>'}</section></div><div class="table-wrap"><table><thead><tr><th>Linked product</th><th>Unit cost</th><th>Available</th><th>Status</th></tr></thead><tbody>${PRODUCTS.filter(p=>p.supplierId===id).map(p=>`<tr><td>${productCell(p)}</td><td>${money(p.cost,2)}</td><td>${p.stock-p.reserved}</td><td>${badge(plan(p).risk)}</td></tr>`).join('')}</tbody></table></div>`}
function scenarioSummary(opts){const t=totals(opts);let remaining=Math.max(0,opts.budget),spend=0;const allocations=new Map();t.rows.slice().sort((a,b)=>b.m.revenue-a.m.revenue||a.p.id-b.p.id).forEach(({p,m})=>{let units=Math.min(m.qty,Math.floor(remaining/p.cost/p.pack)*p.pack);if(units<p.moq)units=0;allocations.set(p.id,units);spend+=units*p.cost;remaining-=units*p.cost});return {...t,allocations,feasibleSpend:spend,remaining,overAfter:t.rows.reduce((a,{p,m})=>a+Math.max(0,simulate(p,{...opts,proposedQty:allocations.get(p.id)||0}).end-m.daily*84)*p.cost,0)}}
function scenarioView(){return `${heading('Plan for the what-ifs.','Try a different future before you commit. Operational stock stays separate.',`<button onclick="resetScenario()">Reset scenario</button>`)}<div class="preset-row"><button onclick="preset('black')">Black Friday demand surge</button><button onclick="preset('delay')">Supplier delayed two weeks</button><button onclick="preset('fall')">Demand falls by 20%</button><button onclick="preset('budget')">Conservative purchasing budget</button></div><div class="scenario-layout"><section class="panel scenario-controls"><h2>Your assumptions</h2><label for="sc-demand">Demand change <span id="demand-value">${scenario.demand}%</span></label><input type="range" id="sc-demand" min="-50" max="100" value="${scenario.demand}" oninput="updateScenario('demand',this.value)"><div class="subtle">Across every product</div><label for="sc-products">Promotional products</label><select id="sc-products" multiple size="5" aria-label="Select promotional products" onchange="scenario.selected=[...this.selectedOptions].map(o=>Number(o.value));refreshScenario()" style="width:100%">${PRODUCTS.map(p=>`<option value="${p.id}" ${scenario.selected.includes(p.id)?'selected':''}>${p.name}</option>`).join('')}</select><div class="subtle">Choose one or more products. On desktop, use Ctrl / Cmd to select several.</div><label for="sc-promo">Promotion uplift <span id="promo-value">${scenario.promo}%</span></label><input type="range" id="sc-promo" min="0" max="150" value="${scenario.promo}" oninput="updateScenario('promo',this.value)"><label for="sc-supplier">Delay applies to</label><select id="sc-supplier" style="width:100%" onchange="updateScenario('supplierId',this.value)"><option value="all">All suppliers</option>${SUPPLIERS.map(s=>`<option value="${s.id}" ${scenario.supplierId===s.id?'selected':''}>${s.name}</option>`).join('')}</select><label for="sc-delay">Delivery delay <span id="delay-value">${scenario.delay} days</span></label><input type="range" id="sc-delay" min="0" max="35" value="${scenario.delay}" oninput="updateScenario('delay',this.value)"><label for="sc-budget">Purchasing budget (£)</label><input type="number" id="sc-budget" min="0" max="1000000" value="${scenario.budget}" style="width:100%" oninput="updateScenario('budget',this.value)"><label for="sc-days">Planning horizon</label><select id="sc-days" style="width:100%" onchange="updateScenario('days',this.value)">${[30,60,90].map(d=>`<option value="${d}" ${scenario.days===d?'selected':''}>${d} days</option>`).join('')}</select><p class="note">These controls do not change your live planning assumptions until you explicitly apply them.</p><button class="primary" onclick="confirmApply()" style="width:100%">Apply to planning</button></section><div class="scenario-results" id="scenario-results">${scenarioResults()}</div></div>`}
function bindScenario(){}
function updateScenario(k,v){scenario[k]=k==='supplierId'?v:Math.max(k==='demand'?-50:0,Math.min(k==='budget'?1000000:1000,Number(v)||0));let el=$('#'+k+'-value');if(el)el.textContent=scenario[k]+(k==='delay'?' days':'%');refreshScenario()}
function refreshScenario(){$('#scenario-results').innerHTML=scenarioResults()}
function resetScenario(){scenario={demand:0,promo:0,selected:[6],delay:0,supplierId:'all',budget:state.settings.budget,days:30};render();toast('Scenario reset to baseline.')}
function preset(kind){scenario={demand:0,promo:0,selected:[6],delay:0,supplierId:'all',budget:state.settings.budget,days:30};if(kind==='black'){scenario.demand=35;scenario.promo=50;scenario.selected=[1,2,6,31,32];scenario.days=60}if(kind==='delay'){scenario.delay=14;scenario.supplierId='s5'}if(kind==='fall')scenario.demand=-20;if(kind==='budget')scenario.budget=3000;render()}
function scenarioResults(){const base=scenarioSummary({days:scenario.days,budget:state.settings.budget}),s=scenarioSummary(scenario),changed=s.rows.filter(({p,m})=>Math.abs(m.revenue-base.rows[p.id-1].m.revenue)>1||m.qty!==base.rows[p.id-1].m.qty||m.out!==base.rows[p.id-1].m.out);return `<div class="intro-banner" style="margin-top:0"><span><strong>Simulated estimates · ${scenario.days} days</strong><br>Stockout risk below is before proposed purchases. Budget allocation does not create orders.</span></div><div class="cards">${stat('Products likely to run out',s.risk,`Baseline <strong>${base.risk}</strong>`,'','red')}${stat('Estimated revenue at risk',money(s.revenue),`Baseline <strong>${money(base.revenue)}</strong>`,'','red')}${stat('Gross profit at risk',money(s.gross),`Baseline <strong>${money(base.gross)}</strong>`)}${stat('Recommended purchasing spend',money(s.feasibleSpend),`Baseline <strong>${money(base.feasibleSpend)}</strong> · within budget`)}${stat('Remaining budget',money(s.remaining),`Unconstrained need ${money(s.spend)}`)}${stat('Expected overstock at horizon',money(s.overAfter),`Baseline <strong>${money(base.overAfter)}</strong> · at unit cost`,'','amber')}</div><section class="panel"><div class="panel-head"><h2>Projected stock, across the range</h2><span class="tag">Before proposed purchases</span></div><div class="legend"><span class="grey">Baseline</span><span>Scenario</span></div>${chart([{values:Array.from({length:scenario.days+1},(_,i)=>base.rows.reduce((a,x)=>a+x.m.trace[i].stock,0)),color:'#a6b6bd'},{values:Array.from({length:scenario.days+1},(_,i)=>s.rows.reduce((a,x)=>a+x.m.trace[i].stock,0)),color:'#147565'}],Array.from({length:scenario.days+1},(_,i)=>'Day '+i),{title:'Baseline and scenario total projected stock'})}</section><section class="panel"><h2>What changed, and why</h2><div class="table-wrap"><table><thead><tr><th>Product</th><th>Forecast / week</th><th>First stockout</th><th>Reorder baseline → scenario</th><th>Budget allocation</th></tr></thead><tbody>${(changed.length?changed:s.rows.filter(x=>x.m.qty>0)).slice().sort((a,b)=>b.m.revenue-a.m.revenue).map(({p,m})=>{let b=base.rows[p.id-1].m;return `<tr><td><a href="#product/${p.id}">${p.name}</a><small class="block subtle">${scenario.selected.includes(p.id)&&scenario.promo?'Promotion +'+scenario.promo+'%. ':''}${scenario.demand?'Demand '+(scenario.demand>0?'+':'')+scenario.demand+'%. ':''}${scenario.delay&&(scenario.supplierId==='all'||scenario.supplierId===p.supplierId)?'Delivery +'+scenario.delay+' days. ':''}${!scenario.demand&&!scenario.promo&&!scenario.delay?'No demand or delivery changes. Budget may restrict purchasing.':''}</small></td><td>${num(b.daily*7,1)} → ${num(m.daily*7,1)}</td><td>${m.out===0?'Already depleted':m.out!==null?date(dateAt(m.out)):'None in horizon'}</td><td>${b.qty} → <strong>${m.qty} units</strong></td><td>${s.allocations.get(p.id)} units${s.allocations.get(p.id)<m.qty?'<small class="block" style="color:var(--amber)">Budget limited</small>':''}</td></tr>`}).join('')||'<tr><td colspan="5">No changes from baseline.</td></tr>'}</tbody></table></div></section><section class="panel"><details open><summary>How this is calculated</summary><p>Daily demand = adjusted six-week mean ÷ 7. Scenario demand multiplies baseline by (1 + demand change); selected promotional products also multiply by (1 + promotion uplift). The range is ±25%, an illustrative assumption. No trained AI model is used.</p><p>Stock is consumed daily. Scheduled and approved deliveries arrive at the start of their expected day; the selected delay shifts these dates and extends replenishment lead time. Unmet units on each day are lost sales, with no back-orders. Retail revenue at risk = unmet units × price. Gross profit at risk = unmet units × (price − unit cost), excluding tax, freight and overheads.</p><p>Reorder target = daily demand × (lead time + safety days), less available units and incoming deliveries due inside that window. Quantity is rounded up to a pack and minimum order. Budget allocation prioritises products by estimated revenue at risk, then SKU order, allocating whole packs that meet the minimum. No allocation is made if the remaining budget cannot cover the minimum.</p><p>Expected overstock = units left at the horizon after consumption and any timely budget-allocated replenishment, above 12 weeks of scenario demand, valued at cost. This is a planning indicator; proposed replenishment is included only when its lead time and delay allow arrival inside the horizon. It does not imply realised savings. Baseline uses the same horizon and the saved demo budget. Current operational planning ${state.applied?'has an applied scenario; this comparison still uses the original baseline.':'uses the baseline.'}</p></details></section>`}
function confirmApply(){openModal(`<h2>Apply these planning assumptions?</h2><p>Demand ${scenario.demand}%, promotional uplift ${scenario.promo}%, delivery delay ${scenario.delay} days. Purchasing budget ${money(scenario.budget)}.</p><p>The recommendations and stock projections will use these assumptions. Warehouse stock, existing orders and previous buyer decisions stay unchanged. No new order is created.</p><div class="actions"><button class="primary" onclick="applyScenario()">Apply to planning</button><button onclick="closeModal()">Keep as scenario</button></div>`)}
function applyScenario(){state.applied=JSON.parse(JSON.stringify(scenario));state.settings.budget=scenario.budget;saveState();closeModal();navigate('overview');toast('Scenario explicitly applied to planning. No orders were created.')}
function clearApplied(){state.applied=null;saveState();render();toast('Baseline planning restored.')}
function performance(){const stable=PRODUCTS.filter(p=>!['new','data','promo','seasonal'].includes(p.flag)),actual=Array.from({length:12},(_,w)=>stable.reduce((a,p)=>a+p.history[w],0)),pred=Array.from({length:12},(_,w)=>stable.reduce((a,p)=>a+Math.round(p.weekly*(.96+.025*Math.cos(p.id+w))),0)),err=actual.reduce((a,v,i)=>a+Math.abs(v-pred[i]),0)/actual.reduce((a,v)=>a+v,0)*100,t=totals(),accepted=state.decisions.filter(d=>d.kind==='Accepted'),overrides=accepted.filter(d=>d.qty!==d.original).length;let sampleAvailability=[95.8,96.4,94.9,96.7,96.1,97.2];return `${heading('Performance','Sample historical results and current demo actions, kept distinct.')}<div class="cards" style="grid-template-columns:repeat(4,1fr)">${stat('Sample forecast error',num(err,1)+'%','Aggregate weekly WAPE · stable lines')}${stat('Current stock availability',num(PRODUCTS.filter(p=>p.stock>p.reserved).length/40*100,1)+'%','Product lines with available units')}${stat('Current overstock at cost',money(t.over),'Above 12 weeks of forecast demand')}${stat('Accepted / revised decisions',accepted.length+' / '+overrides,'Current demo actions, not savings')}</div><div class="grid-two"><section class="panel"><div class="panel-head"><h2>Forecast versus actual sales</h2><span class="tag">Historical sample</span></div><div class="legend"><span class="grey">Actual</span><span>Sample forecast</span></div>${chart([{values:actual,color:'#9aafb9'},{values:pred,color:'#147565',dash:true}],actual.map((_,i)=>'W'+(i+1)),{title:'Historical sample weekly forecasts and actual units sold'})}<p class="note">Includes ${stable.length} stable products. New, promotional, seasonal and poor-data products are excluded. Sample forecasts were constructed for demonstration and are not a validated backtest.</p></section><section class="panel"><h2>Product availability</h2>${chart([{values:sampleAvailability,color:'#147565'}],['May','Jun','Jul','Aug','Sep','Oct'],{max:100,title:'Sample historical product stock availability percentages'})}<p class="note">Six invented historical monthly snapshots, separate from today’s calculated stock availability. Availability = lines with available stock ÷ lines in sample. It is not an order-fill rate.</p></section></div><div class="grid-two"><section class="panel"><h2>Buyer actions in this demo</h2><dl class="key-values"><dt>Accepted recommendations</dt><dd>${accepted.length}</dd><dt>Accepted with quantity override</dt><dd>${overrides}</dd><dt>Rejected</dt><dd>${state.decisions.filter(d=>d.kind==='Rejected').length}</dd><dt>Deferred</dt><dd>${state.decisions.filter(d=>d.kind==='Deferred').length}</dd><dt>Draft quantities revised later</dt><dd>${state.decisions.filter(d=>d.kind==='Order quantity revised').length}</dd><dt>Approved orders</dt><dd>${state.orders.filter(o=>o.status==='Approved').length}</dd></dl><p class="note">Actions are counts, so a product reviewed twice can contribute two decisions. No savings or delivered service improvements are claimed.</p></section><section class="panel"><h2>Historical sample buyer behaviour</h2><dl class="key-values"><dt>Sample recommendations</dt><dd>80</dd><dt>Accepted without change</dt><dd>48 · 60%</dd><dt>Accepted with quantity override</dt><dd>16 · 20%</dd><dt>Rejected</dt><dd>10 · 12.5%</dd><dt>Deferred</dt><dd>6 · 7.5%</dd></dl><p class="note">Illustrative previous-period results. These do not include your current demo decisions.</p></section></div><section class="panel"><h2>How to interpret the numbers</h2><p class="explain">Weekly aggregate WAPE = sum of absolute differences between predicted and actual weekly total units ÷ sum of actual units × 100. Lower is better; 0% is perfect. Aggregate errors can hide product-level errors. Where actual demand is zero, WAPE is not defined and no percentage is reported.</p><p class="explain">Revenue at risk estimates sales that stock cannot support. Gross profit at risk deducts purchase cost only. Overstock is a cost-based cash indicator, not revenue. Dashboard values cover the 40-product sample and should never be compared directly with the company-wide £1.6m lost-sales estimate.</p><a href="#help/metrics">Read the performance guide</a></section>`}
const HELP=[['review','Reviewing a recommendation','Use demand, timing, warning flags and purchasing constraints to make a recorded buyer decision.'],['stock','Stock cover and buying constraints','Understand available units, incoming deliveries, lead times, minimum orders and pack sizes.'],['forecast','Forecasts and scenarios','See the deterministic calculations and the limits of estimates for unusual products.'],['orders','Purchase order workflow','Move from recommendations to supplier drafts and simulated approval.'],['metrics','Performance measures','Read forecast error, availability, revenue at risk and overstock without confusing them.'],['oversight','AI use and human oversight','The practical policy that keeps buyers responsible for every purchasing decision.'],['quality','Data quality guide','Find missing history, spikes, stale supplier records and reconciliation problems.'],['incidents','Report an incident','Log a demo issue, identify the SKU and track investigation status.']];
function help(){return `${heading('Help and guidance','Practical guidance for responsible buying and reliable data.')}<div class="help-grid">${HELP.map(([id,title,desc])=>`<a href="#help/${id}" class="help-card"><h3>${title}</h3><p class="subtle">${desc}</p></a>`).join('')}</div><section class="panel" style="margin-top:24px"><h2>Need a quick answer?</h2><p>Start with the product’s sales history, stock projection and warning panel. If a recommendation seems unusual, defer it and log an incident rather than approving it automatically.</p><a class="button primary" href="#help/incidents">Report an incident</a></section>`}
function helpArticle(id){if(id==='incidents')return incidents();const a=HELP.find(x=>x[0]===id)||HELP[0],content={
review:`<h2>1. Check the product and demand</h2><p>Open a recommendation and compare the last 12 weeks of sales with the weekly forecast. Check whether a promotion, seasonal range change or missing week explains a difference. Demand estimates are buying aids.</p><h2>2. Check stock and timing</h2><p>Available units are warehouse stock minus reservations. Review incoming quantities and dates, then the first projected stockout. If replenishment arrives too late, contact the fictional supplier outside the demo workflow or record an expedited-delivery assumption in a note.</p><h2>3. Check quantity and cost</h2><p>Suggested quantity targets demand over lead time plus the planning safety buffer, less available stock and timely incoming units. Orders must meet the supplier’s minimum per product and be a whole number of packs. The review shows purchase cost and the projected stock impact before acceptance.</p><h2>4. Make your decision</h2><p>Accept, revise, reject or defer. A reason is required for quantity revisions, rejection and deferral. Warning-flagged products require an explicit acknowledgement. Add a note whenever there is relevant context. Acceptance creates a draft line; it never submits an order.</p><h2>5. Follow through</h2><p>Open the supplier purchase order, review the combined cost and quantities, then approve only when satisfied. The audit trail records Sofia Greco, timestamp, original suggestion, chosen quantity and reason. Deferrals remain visible for another review; they do not expire automatically.</p>`,
stock:`<h2>Available stock and stock cover</h2><p>Available units = warehouse units − reserved units. Stock cover in days = available units ÷ baseline daily forecast. Incoming deliveries are excluded from cover because they are not yet available, but are included in projections.</p><p>Already depleted stock has zero cover and is marked out of stock. With zero forecast demand, cover is shown as “No demand”, rather than an infinite or misleading number. Missing weeks are not treated as zero demand; they are excluded and flagged.</p><h2>Lead time</h2><p>Lead time is the expected number of calendar days from approval to arrival at the Manchester warehouse. Customs and transit are included in the European and Asian supplier examples. A scenario delay extends lead time and shifts existing incoming dates for the selected supplier.</p><h2>Minimum order and pack size</h2><p>The minimum is per product, not per supplier order. If the minimum is 24 and the pack is 6, valid quantities are 24, 30, 36 and so on. Quantities below the minimum or outside pack multiples cannot be accepted.</p><h2>Overstock</h2><p>Overstock units = max(available units − 84 days of forecast demand, 0). Cash tied up = overstock units × unit purchase cost. This is a planning threshold, not a valuation adjustment. For a zero-demand product all available units are counted as overstock cash.</p>`,
forecast:`<h2>A transparent baseline</h2><p>The baseline uses the mean of the latest six valid weekly observations divided by seven. Promotional weeks are adjusted to remove the known 65% uplift. The poor-data product excludes its unexplained spike and missing week. Seasonal demand is multiplied by 1.35. New-product estimates blend early sales with a similar-product assumption.</p><p>The indicative uncertainty range is baseline ±25%. It is deliberately simple and is not a calibrated confidence interval. No trained AI model makes these estimates.</p><h2>How projections work</h2><p>Stock is consumed each calendar day. Incoming units are added at the start of the expected arrival day. If demand exceeds available stock, unmet demand is counted as lost and stock stops at zero. No back-orders are created. Draft purchase orders are excluded; approved orders are included.</p><h2>Using scenarios</h2><p>Adjust overall demand, selected promotion uplift, supplier delay, budget and horizon. Presets are starting assumptions. Budget allocation uses estimated revenue at risk, whole packs and minimum quantities. Scenario changes remain separate until you choose “Apply to planning” and confirm.</p><h2>Where estimates need extra care</h2><p>New products have too little history for a dependable pattern. Seasonal products need dates and external context. Promotions can pull purchases forward rather than create lasting demand. Unreliable suppliers can invalidate an otherwise sensible forecast. For all of these, review the assumptions, acknowledge warnings and keep a reason in the decision history.</p>`,
orders:`<h2>Drafting</h2><p>Accepted recommendations are grouped into draft purchase orders by supplier. A product cannot be added twice while it already appears in an order. Edit the draft’s quantity instead. Removing a line records the removal; you may then review that product again.</p><h2>Review and approval</h2><p>Check every line’s cost, MOQ and pack size, the combined total and the arrival date. The purchasing budget is a review guideline. Use the separate approval action and confirm that this is a simulated order. Empty drafts cannot be approved.</p><h2>After approval</h2><p>Approved lines appear as incoming stock on their estimated arrival date. Current warehouse stock stays unchanged. There is no automatic goods receipt and no real supplier contact. Approved orders are read-only in this demo; log an incident if a correction is required.</p><h2>What is recorded</h2><p>Buyer decisions, line revisions and removals are retained with user and time. Approval has its own timestamp. Unit costs exclude VAT, freight and payment costs. All data is saved to this browser and can be reset from Settings.</p>`,
metrics:`<h2>Forecast error</h2><p>The historical sample uses aggregate weekly WAPE: sum(|forecast weekly total − actual weekly total|) ÷ sum(actual weekly totals) × 100. Zero actual demand makes the denominator unusable; report an undefined result rather than 0%. Low aggregate error may hide individual product errors.</p><h2>Availability</h2><p>Current availability is the percentage of demonstration products with available stock above zero. It does not weight products by demand and is not a customer order-fill rate. Historical monthly points are invented examples and are labelled as such.</p><h2>Money measures</h2><p>Revenue at risk multiplies unmet daily units by retail price. Gross profit at risk deducts unit purchase cost, excluding overheads. Overstock cash values excess available units at cost. None of these is a claim of achieved savings.</p><h2>Decision measures</h2><p>Acceptance counts buyer actions. Overrides count accepted quantities that differ from the original suggestion. Repeated reviews may produce multiple actions. Current demo actions are separated from the fixed historical sample of 80 recommendations.</p>`,
oversight:`<h2>Purpose and scope</h2><p>This fictional internal policy applies to demand planning and replenishment. The demo uses deterministic calculations rather than a trained AI model. The same oversight principles would apply to a future model-based tool.</p><h2>Buyer authority</h2><p>Sofia Greco and the merchandising team retain purchasing authority. A system recommendation is not an instruction. No recommendation may automatically submit an order or bypass commercial approval. Buyers must understand cost, timing and stock impact before approving.</p><h2>Required review</h2><ul><li>Check unusual volume, price, demand changes and supplier constraints.</li><li>Explicitly acknowledge new-product, promotion, seasonal, supplier reliability and poor-data warnings.</li><li>Record a reason for overrides, rejection and deferral.</li><li>Escalate recommendations above budget or inconsistent with source records.</li></ul><h2>Errors and incidents</h2><p>Defer the affected recommendation, add a buyer note and log an incident with its SKU, category and description. The merchandising lead checks business impact; a data owner reconciles the source. Record the cause, correction and evidence before resolving. Re-review any affected draft orders after correction.</p><h2>Responsible data use</h2><p>Use product, supplier and aggregate sales data only. Do not add customer information, bank details or confidential real business data to this demo. Browser records are local and are not a shared audit system. Resetting clears them.</p><h2>Monitoring</h2><p>Review error, availability and override patterns monthly. Inspect seasonal and promotional lines separately. A consistently overridden recommendation is a reason to investigate assumptions, rather than to remove buyer control.</p>`,
quality:`<h2>Check completeness</h2><p>Confirm SKU, category, stock, reserved units, unit cost, supplier, lead time, pack size and minimum order are present. Twelve weeks of sales should be dated and use a single definition of units sold. A missing week must be shown as missing, not silently filled with zero.</p><h2>Check consistency</h2><p>Warehouse stock cannot be negative. Reservations must not exceed stock. Incoming quantities need unique delivery references and dates. Costs must be in GBP and use the same tax basis. Reconcile inventory and order lines before trusting aggregate totals.</p><h2>Check plausibility</h2><p>Investigate sudden sales spikes, price changes, stale lead times and demand after a product is discontinued. Keep promotion flags and start/end dates alongside sales. Supplier reliability should have a clear denominator and an agreed definition of on-time delivery.</p><h2>Examples in this demo</h2><p>Steel Deep Casserole has a missing week and a threefold spike; its baseline excludes the unexplained spike. Blend Pro Glass Blender has only three weeks of history. Blend Go Personal Blender has a recent promotion whose uplift is removed from baseline. These products require acknowledgement before acceptance.</p><h2>Fix and verify</h2><p>Log the problem, identify the responsible source, record the correction and rerun the forecast. Compare both product details and dashboard totals. Keep the original value and explanation in a real audit trail; do not quietly overwrite a business decision.</p>`};return `<p><a href="#help">Back to help and guidance</a></p>${heading(a[1],a[2])}<article class="panel article">${content[id]||content.review}</article>`}
function incidents(){return `<p><a href="#help">Back to help and guidance</a></p>${heading('Incident log','Flag a problem, record its impact and track the investigation.')}<div class="grid-two"><section class="panel"><h2>Report a demo incident</h2><form onsubmit="saveIncident(event)"><label for="incident-category">Category</label><select id="incident-category" required><option>Data quality</option><option>Forecast anomaly</option><option>Supplier timing</option><option>Purchase order</option><option>Accessibility</option></select><label for="incident-sku">Affected SKU</label><select id="incident-sku"><option value="">Not product specific</option>${PRODUCTS.map(p=>`<option value="${p.sku}">${p.sku} · ${p.name}</option>`).join('')}</select><label for="incident-description">Description and business impact</label><textarea id="incident-description" minlength="10" required placeholder="What happened, what was expected, and which decision might be affected? Use fictional data only."></textarea><button class="primary">Save demo incident</button><p class="note">Saved only in this browser. Nothing is sent to a real support team.</p></form></section><section class="panel"><h2>Investigation workflow</h2><ol><li>Record the issue and defer affected buying decisions.</li><li>Set the incident to “Investigating” and review source data and open drafts.</li><li>Record a cause and corrective action in the resolution note.</li><li>Set “Resolved” only after verifying the correction.</li></ol><p class="subtle">Demo owner: merchandising lead. Real incidents would require a named investigator, shared record and business escalation.</p></section></div><section class="panel"><h2>Saved incidents</h2>${state.incidents.map(i=>`<div class="history"><div class="panel-head"><strong>${i.id} · ${esc(i.category)} · ${esc(i.sku||'General')}</strong><span class="tag ${i.status==='Resolved'?'teal':'amber'}">${i.status}</span></div><p>${esc(i.description)}</p><small>${stamp(i.time)} · Sofia Greco</small>${i.resolution?`<p><strong>Resolution:</strong> ${esc(i.resolution)}</p>`:''}<div class="actions"><button onclick="editIncident('${i.id}')">Update status / resolution</button></div></div>`).join('')||'<p class="subtle">No incidents logged.</p>'}</section>`}
function saveIncident(e){e.preventDefault();state.incidents.push({id:'INC-'+String(state.incidents.length+1).padStart(3,'0'),category:$('#incident-category').value,sku:$('#incident-sku').value,description:$('#incident-description').value.trim(),status:'Open',resolution:'',time:new Date().toISOString()});saveState();render();toast('Demo incident saved locally. Nothing was sent.')}
function editIncident(id){const i=state.incidents.find(i=>i.id===id);openModal(`<h2>Update ${id}</h2><form onsubmit="updateIncident(event,'${id}')"><label for="incident-status">Status</label><select id="incident-status">${options(['Open','Investigating','Resolved'],i.status)}</select><label for="incident-resolution">Investigation / resolution note</label><textarea id="incident-resolution">${esc(i.resolution)}</textarea><div id="incident-error" class="error" role="alert"></div><div class="actions"><button class="primary">Save update</button><button type="button" onclick="closeModal()">Cancel</button></div></form>`)}
function updateIncident(e,id){e.preventDefault();let i=state.incidents.find(i=>i.id===id),status=$('#incident-status').value,note=$('#incident-resolution').value.trim();if(status==='Resolved'&&!note){$('#incident-error').textContent='Record the cause, correction and verification before resolving.';return}i.status=status;i.resolution=note;saveState();closeModal();render();toast('Incident updated.')}
function settings(){return `${heading('Settings','Planning preferences for this browser’s demo workspace.')}<section class="panel article"><h2>Planning preferences</h2><form onsubmit="saveSettings(event)"><div class="form-grid"><div><label for="setting-budget">Demo purchasing budget (£)</label><input type="number" id="setting-budget" min="0" max="1000000" step="100" value="${state.settings.budget}" required></div><div><label for="setting-safety">Safety stock buffer (days)</label><input type="number" id="setting-safety" min="0" max="60" step="1" value="${state.settings.safety}" required></div></div><p class="subtle">The overview always reports a 30-day risk window. Stock cover uses available units; the overstock threshold stays at 12 weeks. Changes affect future recommendations, not orders already created.</p><button class="primary">Save preferences</button></form><h2>Workspace identity</h2><dl class="key-values"><dt>User</dt><dd>Sofia Greco</dd><dt>Role</dt><dd>Senior Merchandiser</dd><dt>Currency / dates</dt><dd>GBP / UK formats</dd><dt>Planning snapshot</dt><dd>9 Oct 2026</dd><dt>Active planning assumptions</dt><dd>${state.applied?'Applied scenario':'Baseline'}</dd></dl>${state.applied?'<button style="margin-top:15px" onclick="clearApplied()">Restore baseline planning</button>':''}<h2>Reset this demo</h2><p>Restore the original 40-product dataset and clear buyer decisions, draft and approved orders, incidents and saved preferences from this browser. Public forms never store personal details.</p><button class="danger" onclick="confirmReset()">Reset demo data</button><p class="note">Changes are stored locally. They are not shared with other devices or browsers.</p></section>`}
function saveSettings(e){e.preventDefault();state.settings.budget=Number($('#setting-budget').value);state.settings.safety=Number($('#setting-safety').value);saveState();toast('Planning preferences saved. Existing orders are unchanged.')}
function confirmReset(){openModal(`<h2>Reset all demo changes?</h2><p>This clears buyer decisions, all purchase orders, saved incidents and planning preferences from this browser. The original sample data will be restored.</p><div class="actions"><button class="danger" onclick="resetDemo()">Confirm reset</button><button onclick="closeModal()">Keep my changes</button></div>`)}
function resetDemo(){state=freshState();saveState();scenario={demand:0,promo:0,selected:[6],delay:0,supplierId:'all',budget:15000,days:30};filters={search:'',category:'all',supplier:'all',risk:'all',sort:'risk',direction:1};closeModal();render();toast('Original demo data restored.')}
const FAQS=[['Is NovaGoods a real retailer?','No. NovaGoods is a fictional Manchester-based retailer used in an interactive business demonstration. Products, suppliers, prices, delivery terms and contacts are invented. You cannot make a real purchase here.'],['What does NovaGoods sell?','Our fictional range covers kitchenware, small kitchen electronics, home décor and fitness accessories. The public catalogue shows the same 40 products used by the Stock Planner.'],['How much is delivery?','Demo terms: standard UK mainland delivery is £3.95, or free for a basket above £50. Express delivery would be £6.95. No checkout or real shipping is available.'],['When would my order arrive?','Demo terms: standard delivery takes 3–5 working days after dispatch and express delivery takes 1–2 working days. Bank holidays and remote locations could take longer. These are fictional service examples.'],['Can I return a product?','Demo terms: request a return within 30 days of delivery, with the item unused and packaging retained. A fictional faulty-goods team would arrange a suitable remedy. No real returns are processed here.'],['Do you deliver outside the UK?','The fictional retail offer is designed for the UK. Northern Ireland, islands and remote postcodes would need a separate delivery quote in a real shop. This demo does not calculate or accept a delivery address.'],['Are the product photos exact?','No. Photographs are illustrative examples of the product type and may show another brand or colour. Descriptions and specifications are fictional NovaGoods data.'],['Can I order an out-of-stock product?','The catalogue is browse-only. In the fictional shop, out-of-stock products would not be sold until stock was received, unless a clearly dated pre-order was offered.'],['What is Stock Planner?','It is an internal workspace where a fictional buyer reviews stock risks, runs deterministic scenarios and records replenishment decisions. No login, customer data or real supplier connection is needed.'],['How can I contact you?','Use the demonstration contact form to see a confirmation. Nothing is sent and entered details are not saved. The example email address uses the reserved .example domain.']];
function renderPublic(path){const key=path.split('/')[1]||'home';$('#app').innerHTML=`<header class="public-header">${logo()}<nav aria-label="NovaGoods website"><a href="#public/home">Home</a><a href="#public/range">Our range</a><a href="#public/about">About</a><a href="#public/help">Help</a><a href="#overview" class="button primary">Open Stock Planner</a></nav></header><main id="main" class="public-main">${publicView(path)}</main><footer class="public-footer"><div>${logo()}<p>Useful things. Thoughtfully chosen.<br>Kitchen, home and everyday movement.</p><div class="demo">Fictional company · Interactive demo</div></div><div><strong>Customer information</strong><a href="#public/delivery">Delivery & returns</a><a href="#public/help">Help centre</a><a href="#public/contact">Contact</a><a href="#public/about">About NovaGoods</a></div><div><strong>Policies</strong><a href="#public/privacy">Privacy notice</a><a href="#public/cookies">Cookie information</a><a href="#public/terms">Website terms</a><a href="#public/accessibility">Accessibility statement</a><a href="#help/oversight">Internal oversight policy</a></div></footer>`}
function publicView(path){const [,key,id]=path.split('/');if(key==='home')return `<section class="hero"><div class="hero-copy"><div class="eyebrow">At home, every day.</div><h1>A little more useful.<br>A little more you.</h1><p>Kitchen essentials, thoughtful finishing touches and room for a healthier routine. Discover everyday goods selected for homes across the UK.</p><a href="#public/range" class="button primary">Explore our range</a><p class="demo" style="margin-top:22px">Fictional company · Interactive demo</p></div>${photo(PRODUCTS[20])}</section><div class="panel-head"><div><div class="eyebrow">This season</div><h2 style="margin:0">Settle into autumn.</h2></div><a href="#public/range">Browse all products</a></div><p class="subtle">A warm lamp, a favourite brew and simple meals at home. Meet a few of our seasonal picks.</p><div class="catalogue">${[1,12,21,26].map(id=>catalogueCard(PRODUCTS[id-1])).join('')}</div><section class="panel" style="margin-top:35px"><div class="grid-two" style="margin:0"><div><div class="eyebrow">Manchester roots · Since 2014</div><h2>Good goods, without the fuss.</h2><p>NovaGoods began with a small kitchenware range and a simple idea: online shopping should make it easier to find useful things you’ll reach for every day. Our fictional Manchester team now works across four ranges.</p><a href="#public/about">Meet NovaGoods</a></div><div><h3>Inside the buying team</h3><p class="subtle">Explore how our merchandising team plans demand, spots stock risks and makes purchasing decisions in the Stock Planner.</p><a href="#overview" class="button primary">Open Stock Planner</a><p class="note">The retail catalogue is browse-only. No real purchases or personal data collection.</p></div></div></section><p class="demo">Product photographs are illustrative and may show other manufacturers. Prices, specifications and availability are fictional demo content.</p>`;if(key==='range')return `<div class="eyebrow">The NovaGoods collection</div><h1>Our range</h1><p class="subtle">Thoughtful essentials for your kitchen, home and daily routine.</p><div class="filters"><input aria-label="Search public products" placeholder="Search products…" value="${esc(catalogueSearch)}" oninput="catalogueSearch=this.value;updateCatalogue()"></div><div class="category-tabs">${['all',...new Set(PRODUCTS.map(p=>p.category))].map(c=>`<button class="${catalogueCategory===c?'active':''}" onclick="catalogueCategory='${c}';render()">${c==='all'?'All products':c}</button>`).join('')}</div><div id="catalogue-results">${catalogueResults()}</div><p class="demo">Illustrative photographs; fictional specifications and prices. Browse-only catalogue, no checkout.</p>`;if(key==='product')return publicProduct(Number(id));if(key==='help')return `<div class="eyebrow">Customer information</div><h1>How can we help?</h1><p>Find an answer about our fictional range and services.</p><div class="filters"><input aria-label="Search frequently asked questions" placeholder="Search delivery, returns, products…" oninput="searchFAQs(this.value)"></div><section class="panel article" id="faq-results">${faqHtml('')}</section>`;if(key==='contact')return `<div class="eyebrow">Customer care</div><h1>Contact NovaGoods</h1><div class="grid-two"><section class="panel"><h2>Try the contact form</h2><p class="subtle">Use fictional details only. Nothing is sent or stored.</p><form class="content-form" onsubmit="contactSubmit(event)"><label for="contact-name">Demo name</label><input id="contact-name" required placeholder="Alex Example" autocomplete="off"><label for="contact-topic">Topic</label><select id="contact-topic"><option>Product question</option><option>Delivery</option><option>Returns</option><option>Accessibility</option><option>Other</option></select><label for="contact-message">Demo message</label><textarea id="contact-message" required placeholder="Write a fictional enquiry…"></textarea><button class="primary">Demonstrate submission</button><div id="contact-confirmation" role="status"></div></form></section><section class="panel"><h2>Customer care details</h2><p><strong>Fictional demo email:</strong><br>hello@novagoods.example</p><p><strong>Demo opening hours:</strong><br>Monday–Friday, 9am–5pm, excluding UK bank holidays.</p><p><strong>Location:</strong><br>Manchester, UK. No real street address or telephone number is provided.</p><p class="note">This is a fictional company. The form does not contact anybody and no real support service is available.</p><a href="#public/help">Browse the help centre</a></section></div>`;return publicArticle(key)}
function catalogueCard(p){return `<a href="#public/product/${p.id}" class="catalogue-card">${photo(p)}<div class="copy"><div class="subtle" style="font-size:12px">${p.category}</div><h3>${p.name}</h3><strong>${money(p.price,2)}</strong><div class="subtle" style="font-size:12px;margin-top:5px">${p.stock-p.reserved>0?'Available in demo':'Out of stock in demo'}</div></div></a>`}
function catalogueResults(){const rows=PRODUCTS.filter(p=>(catalogueCategory==='all'||p.category===catalogueCategory)&&p.name.toLowerCase().includes(catalogueSearch.toLowerCase()));return `<div class="catalogue">${rows.map(catalogueCard).join('')}</div>${!rows.length?'<div class="empty">No products found. Try a different name or category.</div>':''}`}
function updateCatalogue(){$('#catalogue-results').innerHTML=catalogueResults()}
function publicProduct(id){const p=PRODUCTS.find(p=>p.id===id);if(!p)return '<h1>Product not found</h1><a href="#public/range">Return to our range</a>';const description=p.category==='Kitchenware'?'Make everyday preparation a little simpler. This practical kitchen essential is selected for easy storage, comfortable handling and regular use.':p.category==='Small electronics'?'A useful addition to the everyday kitchen, designed around straightforward controls and the tasks you do most often. Give it a dedicated place on the worktop and enjoy a simpler routine.':p.category==='Home décor'?'Bring a thoughtful finishing touch to your space. Its understated shape works with relaxed interiors, whether you’re refreshing a favourite corner or putting together a new room.':'Make room for movement at home. This compact fitness essential is easy to store between sessions and helps you build a routine at your own pace.';return `<p><a href="#public/range">Back to our range</a></p><section class="public-product">${photo(p)}<div><div class="eyebrow">${p.category} · ${p.sku}</div><h1>${p.name}</h1><p class="price">${money(p.price,2)}</p><span class="tag ${p.stock-p.reserved>0?'teal':'red'}">${p.stock-p.reserved>0?'Available · '+(p.stock-p.reserved)+' demo units':'Out of stock'}</span><p>${description}</p><h3>Specifications</h3><ul>${p.specs.split(' • ').map(s=>`<li>${esc(s)}</li>`).join('')}</ul><h3>Care and use</h3><p class="subtle">${p.category==='Small electronics'?'Read the supplied instructions, keep electrical parts dry and unplug before cleaning. Allow heated surfaces to cool.':p.category==='Kitchenware'?'Wash before first use. Use non-abrasive cleaning tools and follow the material-specific care instructions.':p.category==='Home décor'?'Dust gently with a soft cloth. Keep away from direct heat and follow any cover or electrical care label.':'Check condition before each use. Clean gently, dry thoroughly and store away from heat. Choose a resistance or weight suited to your ability.'}</p><a class="button" href="#public/delivery">Delivery and returns information</a><p class="note">Fictional product and price. Photograph is illustrative, may show another manufacturer and is not an exact specification. This catalogue has no checkout.</p></div></section><h2 style="margin-top:40px">More in ${p.category.toLowerCase()}</h2><div class="catalogue">${PRODUCTS.filter(x=>x.category===p.category&&x.id!==p.id).slice(0,4).map(catalogueCard).join('')}</div>`}
function faqHtml(q){const rows=FAQS.filter(([a,b])=>(a+' '+b).toLowerCase().includes(q.toLowerCase()));return rows.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')||'<p>No matching answers. Try another word or use the demonstration contact form.</p>'}
function searchFAQs(q){$('#faq-results').innerHTML=faqHtml(q)}
function contactSubmit(e){e.preventDefault();e.target.reset();$('#contact-confirmation').innerHTML='<div class="summary"><strong>Demo submission complete.</strong> Nothing was sent and no personal details were saved.</div>'}
function publicArticle(key){const pages={
about:['About NovaGoods',`<div class="eyebrow">A Manchester story</div><h2>Everyday goods, thoughtfully chosen.</h2><p>NovaGoods is a fictional online retailer founded in Manchester in 2014. It began with a focused kitchenware collection and grew around products that make everyday life a little easier: reliable countertop essentials, practical storage, finishing touches for the home and compact fitness accessories.</p><p>In this case-study business, around 180 colleagues work across buying, customer care, warehouse operations and the teams behind the website. Four merchandisers plan demand and replenishment for roughly 1,250 active product lines.</p><h2>How we source</h2><p>The fictional buying team works with UK and European distributors and selected manufacturers in Asia. It balances cost, lead time and delivery reliability, reviewing product information before adding a range. This demonstration does not claim certification, independent audits or verified sourcing standards.</p><h2>The business in context</h2><div class="company-facts">${stat('Annual turnover','≈ £38m','Company-wide case-study figure')}${stat('Monthly orders','≈ 70,000','Company-wide; £45 average order')}${stat('Active product lines','≈ 1,250','40 products in this demonstration')}${stat('Returning customers','≈ 40%','Share of company-wide orders')}${stat('Gross / net margin','≈ 42% / 5%','Company-wide background figures')}${stat('Employees','≈ 180','One Manchester warehouse')}</div><p>Company-wide estimates include 7% of lines out of stock, £1.6m in annual lost sales, £1.1m in slow-moving overstock and £600,000 in annual markdowns. These are case-study background figures, not totals calculated from this 40-product demo. Monthly orders and order value imply about £37.8m annual revenue, rounded to £38m.</p><h2>Planning a better-stocked range</h2><p>Our Stock Planner brings demand, delivery timing and buying decisions into one shared view. It lets the fictional merchandising team inspect estimates and scenarios while retaining responsibility for every purchase.</p><a href="#overview" class="button primary">Open Stock Planner</a>`],
delivery:['Delivery and returns',`<div class="warning">All service terms on this page are fictional demo content. No orders, deliveries or returns are processed.</div><h2>UK delivery</h2><p>Example standard UK mainland delivery costs £3.95 and is free above a £50 basket value. Delivery would normally take 3–5 working days after dispatch. Example express delivery costs £6.95 and would take 1–2 working days.</p><p>These times exclude bank holidays. Islands, remote postcodes and Northern Ireland would require a separate quote in a real service. The demo accepts no delivery address and offers no checkout.</p><h2>Dispatch and tracking</h2><p>In this fictional service, orders placed before noon on a working day would normally be prepared that day if all items were available. A dispatch message would give a carrier reference. Stock shown in the catalogue is the demonstration warehouse’s available quantity.</p><h2>Change-of-mind returns</h2><p>Example policy: request a return within 30 days of receipt, with the goods unused and their packaging retained. Return postage for a change of mind would be paid by the customer. A fictional refund would be issued to the original payment method after inspection, normally within 14 days.</p><h2>Damaged or faulty goods</h2><p>A real customer care team would ask for the order reference and a description of the fault, then arrange an appropriate remedy. These fictional examples do not limit statutory rights or provide advice about a real purchase. No real dispute or refund can be handled here.</p><h2>How to try the workflow</h2><p>Use the contact form with a fictional enquiry. It confirms the demo submission and tells you that nothing was sent.</p><a href="#public/contact" class="button">Open demo contact form</a>`],
privacy:['Privacy notice',`<p>This notice explains the fictional NovaGoods demonstration. NovaGoods is not a real trading business or data controller, and the site does not operate a shop.</p><h2>Information entered in forms</h2><p>The public contact form is a simulation. It does not send or save its contents. Use fictional details only. There is no account registration, payment collection or delivery-address collection.</p><h2>Local workspace records</h2><p>The Stock Planner saves demo buyer decisions, purchase orders, planning settings and incidents in this browser’s local storage. The named user, Sofia Greco, is fictional. Please do not enter real personal, customer or confidential information in notes or incident descriptions.</p><h2>Clearing records</h2><p>Use Settings → Reset demo data to clear saved workspace changes. Clearing the browser’s site data also removes them. Records are not shared between devices, and they remain on the device until cleared.</p><h2>Hosting and third-party resources</h2><p>The hosting service may handle technical request information under its own policies. Illustrative product photos and fonts may load from external providers, which can receive ordinary browser request information such as IP address. This demonstration adds no analytics, advertising or tracking scripts.</p><h2>Questions</h2><p>The example contact address is hello@novagoods.example and does not represent a real inbox. For actual hosting or account privacy questions, consult the hosting provider’s policies and account support.</p>`],
cookies:['Cookie information',`<h2>How this demo uses storage</h2><p>The NovaGoods application sets no application cookies and uses no analytics or advertising trackers. The hosting platform may use its own essential access or session mechanisms, separate from the application.</p><h2>Local storage</h2><p>Browser local storage keeps buyer decisions, purchase orders, incidents and planning preferences under the name “novagoods-v1”. It is necessary for the requested demo changes to survive reloads. It is not a cookie and is not sent by the application to a server.</p><h2>Your choices</h2><p>Reset demo data in Settings to return to the original sample. You can also delete the site’s data in browser settings. Blocking storage allows browsing, but changes may not persist. There are no optional advertising or analytics cookies to switch on.</p><h2>External images and fonts</h2><p>Illustrative product images and fonts are requested from their source providers. They may be subject to those providers’ own browser storage practices. The application does not add a tracking identifier to these requests.</p><a href="#settings" class="button">Open demo settings</a>`],
terms:['Website terms',`<h2>Demonstration only</h2><p>NovaGoods is a fictional UK retailer. The website and Stock Planner are an interactive case-study demonstration. Company figures, staff identities, suppliers, products, prices, commercial terms and recommendations are invented. No company registration number or certification is claimed.</p><h2>Browsing the catalogue</h2><p>The catalogue does not offer checkout. Products cannot be bought, reserved or shipped. Specifications are illustrative and product photographs may depict other manufacturers. They are not a promise of real goods, availability or performance.</p><h2>Using the workspace</h2><p>Recommendations and scenarios are deterministic simulated estimates. They are not financial advice or validated forecasts. Acceptance and approval actions only change demo records. No supplier is contacted and no real funds are committed.</p><h2>Responsible use</h2><p>Use fictional data only. Do not put personal information, credentials or confidential business records into forms. Browser storage is device-specific; deleting it or resetting the demo removes your changes.</p><h2>Images and content</h2><p>The NovaGoods mark is an original demo identity. Illustrative photographs remain subject to their source providers’ rights; no ownership or endorsement by the depicted manufacturers is claimed. This private demonstration is not a production retail offering.</p><h2>Changes and support</h2><p>The demo may be edited or reset. Public contact submissions are simulated and produce no real support request. Fictional delivery and returns examples describe an imagined service only.</p>`],
accessibility:['Accessibility statement',`<h2>Our approach</h2><p>This demonstration aims to be usable on desktop, iPad and smaller screens. It uses labelled controls, visible keyboard focus, semantic headings, text status labels and navigation links. This is a description of design intent, not a certification or legal compliance claim.</p><h2>Using the site</h2><p>Use Tab to move between links and controls, Enter to activate links and buttons, and Escape to close a dialog. The “Skip to content” link appears when focused. Browser zoom and larger text settings are supported. Wide inventory tables can be scrolled horizontally.</p><h2>Charts and alternatives</h2><p>Charts have descriptive labels. Key results are also shown as numbers, product tables and written explanations. Stock status is expressed in words as well as colour. Product photographs have type-based alternative text and are labelled illustrative.</p><h2>Known limitations</h2><p>Dense tables may require horizontal scrolling on small screens. The multi-select promotion list uses the browser’s native control and behaves differently across devices. The demo has not had a formal assistive-technology audit. External image availability depends on the source provider.</p><h2>Report a problem</h2><p>Use the Stock Planner incident form and choose “Accessibility”, or try the public contact form. Both are local demonstrations; no message reaches a real support team.</p><a href="#help/incidents" class="button">Log a demo accessibility incident</a>`]
};const page=pages[key];if(!page)return '<h1>Page not found</h1><a href="#public/home">Return home</a>';return `<h1>${page[0]}</h1><article class="panel article" style="margin-top:25px">${page[1]}</article>`}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_inventory',description:'Read current demo inventory and stock planning results. No state changes.',inputSchema:{type:'object',properties:{sku:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input.sku&&typeof input.sku!=='string')throw Error('SKU must be text');const rows=PRODUCTS.filter(p=>!input.sku||p.sku===input.sku);if(input.sku&&!rows.length)throw Error('SKU not found');return rows.map(p=>({sku:p.sku,name:p.name,available:p.stock-p.reserved,recommendation:plan(p).qty,risk:plan(p).risk}))}});document.modelContext.registerTool({name:'open_recommendation_review',description:'Open the buyer review dialog for a SKU. This does not accept a recommendation or create an order.',inputSchema:{type:'object',properties:{sku:{type:'string'}},required:['sku'],additionalProperties:false},execute(input){const p=PRODUCTS.find(p=>p.sku===input.sku);if(!p)throw Error('SKU not found');review(p.id);return {sku:p.sku,reviewOpened:$('#modal').open,existingOrder:state.orders.find(o=>o.lines.some(l=>l.productId===p.id))?.id||null}}})}catch(e){console.warn('Browser tool registration unavailable',e)}}
render();
